-- Two Sum Indices (Easy)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$two-sum-indices$q$, $q$Two Sum Indices$q$, $q$Given an array of integers and a target value T, find two different positions i < j such that a[i] + a[j] = T.

If several pairs exist, print the pair with the smallest i. If that still leaves several choices, print the one with the smallest j. If no pair exists, print -1.$q$, $q$Easy$q$, $q$Arrays$q$, 'code', ARRAY[$q$array$q$, $q$hash-map$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # Line 1: two integers n and T.\n    # Line 2: n integers a[0] … a[n-1].\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// Line 1: two integers n and T.\n// Line 2: n integers a[0] … a[n-1].\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // Line 1: two integers n and T.\n        // Line 2: n integers a[0] … a[n-1].\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // Line 1: two integers n and T.\n    // Line 2: n integers a[0] … a[n-1].\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // Line 1: two integers n and T.\n    // Line 2: n integers a[0] … a[n-1].\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "4 9\n2 7 11 15", "output": "0 1", "explanation": "a[0] + a[1] = 2 + 7 = 9."}, {"input": "3 6\n3 2 4", "output": "1 2", "explanation": "Only 2 + 4 reaches 6. Using 3 twice is not allowed."}]$q$::jsonb, ARRAY[$q$2 ≤ n ≤ 10 000$q$, $q$-10^9 ≤ a[i] ≤ 10^9$q$, $q$-2·10^9 ≤ T ≤ 2·10^9$q$]::text[], 10, 1001, 2000, 262144, $q$Line 1: two integers n and T.
Line 2: n integers a[0] … a[n-1].$q$, $q$Two integers i and j separated by a space (0-based), or -1.$q$, $q$Checking every pair is O(n²) and too slow for n = 50 000. Walk the array from right to left and keep a map from value to the smallest index seen so far to the right. For each i, look up T - a[i]. A hit gives the best j for that i. Because i decreases, the last hit recorded is the one with the smallest i. Total time O(n).$q$, false)
ON CONFLICT (slug) DO NOTHING;

